exercises.solutionCode:
#include <stdint.h>

static int bit_index_valid(int n)
{
    return (n >= 0 && n <= 31);
}

uint32_t set_bit(uint32_t reg, int n)
{
    if (!bit_index_valid(n)) {
        return reg;
    }
    return reg | (1u << n);
}

uint32_t clear_bit(uint32_t reg, int n)
{
    if (!bit_index_valid(n)) {
        return reg;
    }
    return reg & ~(1u << n);
}

uint32_t toggle_bit(uint32_t reg, int n)
{
    if (!bit_index_valid(n)) {
        return reg;
    }
    return reg ^ (1u << n);
}
